  'enem-2026-reference-matrix-v1','draft',now(),null,$framework${"schema_version":1,"framework_type":"enem_reference_matrix","cognitive_axes":[{"code":"I","name":"Dominar linguagens (DL)","text":"dominar a norma culta da língua portuguesa e fazer uso das linguagens matemática, artística e científica e das línguas espanhola e inglesa","source_page":9},{"code":"II","name":"Compreender fenômenos (CF)","text":"construir e aplicar conceitos das várias áreas do conhecimento para a compreensão de fenômenos naturais, de processos histórico-geográficos, da produção tecnológica e das manifestações artísticas","source_page":9},{"code":"III","name":"Enfrentar situações-problema (SP)","text":"selecionar, organizar, relacionar, interpretar dados e informações, representados de diferentes formas, para tomar decisões e enfrentar situações-problema","source_page":9},{"code":"IV","name":"Construir argumentação (CA)","text":"relacionar informações, representadas em diferentes formas, e conhecimentos disponíveis em situações concretas, para construir argumentação consistente","source_page":9},{"code":"V","name":"Elaborar propostas (EP)","text":"recorrer aos conhecimentos desenvolvidos na escola para elaboração de propostas de intervenção solidária na realidade, respeitando os valores humanos e considerando a diversidade sociocultural","source_page":9}],"areas":[{"code":"languages","name":"Linguagens, Códigos e suas Tecnologias","competencies":[{"code":"languages.C1","number":1,"text":"Aplicar as tecnologias da comunicação e da informação na escola, no trabalho e em outros contextos relevantes para sua vida.","source_page":10,"abilities":[{"code":"languages.H1","number":1,"text":"Identificar as diferentes linguagens e seus recursos expressivos como elementos de caracterização dos sistemas de comunicação.","source_page":10},{"code":"languages.H2","number":2,"text":"Recorrer aos conhecimentos sobre as linguagens dos sistemas de comunicação e informação para resolver problemas sociais.","source_page":10},{"code":"languages.H3","number":3,"text":"Relacionar informações geradas nos sistemas de comunicação e informação, considerando a função social desses sistemas.","source_page":10},{"code":"languages.H4","number":4,"text":"Reconhecer posições críticas aos usos sociais que são feitos das linguagens e dos sistemas de comunicação e informação.","source_page":10}]},{"code":"languages.C2","number":2,"text":"Conhecer e usar língua(s) estrangeira(s) moderna(s) como instrumento de acesso a informações e a outras culturas e grupos sociais.","source_page":11,"abilities":[{"code":"languages.H5","number":5,"text":"Associar vocábulos e expressões de um texto em LEM ao seu tema.","source_page":11},{"code":"languages.H6","number":6,"text":"Utilizar os conhecimentos da LEM e de seus mecanismos como meio de ampliar as possibilidades de acesso a informações, tecnologias e culturas.","source_page":11},{"code":"languages.H7","number":7,"text":"Relacionar um texto em LEM, as estruturas linguísticas, sua função e seu uso social.","source_page":11},{"code":"languages.H8","number":8,"text":"Reconhecer a importância da produção cultural em LEM como representação da diversidade cultural e linguística.","source_page":11}]},{"code":"languages.C3","number":3,"text":"Compreender e usar a linguagem corporal como relevante para a própria vida, integradora social e formadora da identidade.","source_page":11,"abilities":[{"code":"languages.H9","number":9,"text":"Reconhecer as manifestações corporais de movimento como originárias de necessidades cotidianas de um grupo social.","source_page":11},{"code":"languages.H10","number":10,"text":"Reconhecer a necessidade de transformação de hábitos corporais em função das necessidades cinestésicas.","source_page":11},{"code":"languages.H11","number":11,"text":"Reconhecer a linguagem corporal como meio de interação social, considerando os limites de desempenho e as alternativas de adaptação para diferentes indivíduos.","source_page":11}]},{"code":"languages.C4","number":4,"text":"Compreender a arte como saber cultural e estético gerador de significação e integrador da organização do mundo e da própria identidade.","source_page":12,"abilities":[{"code":"languages.H12","number":12,"text":"Reconhecer diferentes funções da arte, do trabalho da produção dos artistas em seus meios culturais.","source_page":12},{"code":"languages.H13","number":13,"text":"Analisar as diversas produções artísticas como meio de explicar diferentes culturas, padrões de beleza e preconceitos.","source_page":12},{"code":"languages.H14","number":14,"text":"Reconhecer o valor da diversidade artística e das inter-relações de elementos que se apresentam nas manifestações de vários grupos sociais e étnicos.","source_page":12}]},{"code":"languages.C5","number":5,"text":"Analisar, interpretar e aplicar recursos expressivos das linguagens, relacionando textos com seus contextos, mediante a natureza, função, organização, estrutura das manifestações, de acordo com as condições de produção e recepção.","source_page":12,"abilities":[{"code":"languages.H15","number":15,"text":"Estabelecer relações entre o texto literário e o momento de sua produção, situando aspectos do contexto histórico, social e político.","source_page":12},{"code":"languages.H16","number":16,"text":"Relacionar informações sobre concepções artísticas e procedimentos de construção do texto literário.","source_page":12},{"code":"languages.H17","number":17,"text":"Reconhecer a presença de valores sociais e humanos atualizáveis e permanentes no patrimônio literário nacional.","source_page":12}]},{"code":"languages.C6","number":6,"text":"Compreender e usar os sistemas simbólicos das diferentes linguagens como meios de organização cognitiva da realidade pela constituição de significados, expressão, comunicação e informação.","source_page":13,"abilities":[{"code":"languages.H18","number":18,"text":"Identificar os elementos que concorrem para a progressão temática e para a organização e estruturação de textos de diferentes gêneros e tipos.","source_page":13},{"code":"languages.H19","number":19,"text":"Analisar a função da linguagem predominante nos textos em situações específicas de interlocução.","source_page":13},{"code":"languages.H20","number":20,"text":"Reconhecer a importância do patrimônio linguístico para a preservação da memória e da identidade nacional.","source_page":13}]},{"code":"languages.C7","number":7,"text":"Confrontar opiniões e pontos de vista sobre as diferentes linguagens e suas manifestações específicas.","source_page":13,"abilities":[{"code":"languages.H21","number":21,"text":"Reconhecer, em textos de diferentes gêneros, recursos verbais e não verbais utilizados com a finalidade de criar e mudar comportamentos e hábitos.","source_page":13},{"code":"languages.H22","number":22,"text":"Relacionar, em diferentes textos, opiniões, temas, assuntos e recursos linguísticos.","source_page":13},{"code":"languages.H23","number":23,"text":"Inferir em um texto quais são os objetivos de seu produtor e quem é seu público-alvo, pela análise dos procedimentos argumentativos utilizados.","source_page":13},{"code":"languages.H24","number":24,"text":"Reconhecer no texto estratégias argumentativas empregadas para o convencimento do público, tais como a intimidação, sedução, comoção, chantagem, entre outras.","source_page":13}]},{"code":"languages.C8","number":8,"text":"Compreender e usar a língua portuguesa como língua materna, geradora de significação e integradora da organização do mundo e da própria identidade.","source_page":14,"abilities":[{"code":"languages.H25","number":25,"text":"Identificar, em textos de diferentes gêneros, as marcas linguísticas que singularizam as variedades linguísticas sociais, regionais e de registro.","source_page":14},{"code":"languages.H26","number":26,"text":"Relacionar as variedades linguísticas a situações específicas de uso social.","source_page":14},{"code":"languages.H27","number":27,"text":"Reconhecer os usos da norma-padrão da língua portuguesa nas diferentes situações de comunicação.","source_page":14}]},{"code":"languages.C9","number":9,"text":"Entender os princípios, a natureza, a função e o impacto das tecnologias da comunicação e da informação na sua vida pessoal e social, no desenvolvimento do conhecimento, associando-os aos conhecimentos científicos, às linguagens que lhes dão suporte, às demais tecnologias, aos processos de produção e aos problemas que se propõem solucionar.","source_page":14,"abilities":[{"code":"languages.H28","number":28,"text":"Reconhecer a função e o impacto social das diferentes tecnologias da comunicação e informação.","source_page":14},{"code":"languages.H29","number":29,"text":"Identificar, pela análise de suas linguagens, as tecnologias da comunicação e informação.","source_page":14},{"code":"languages.H30","number":30,"text":"Relacionar as tecnologias de comunicação e informação ao desenvolvimento das sociedades e ao conhecimento que elas produzem.","source_page":14}]}],"object_groups":[{"title":"Estudo do texto: as sequências discursivas e os gêneros textuais no sistema de comunicação e informação","subject_code":"languages_codes","source_page":33,"items":[{"text":"Modos de organização da composição textual","source_page":33},{"text":"Atividades de produção escrita e de leitura de textos gerados nas diferentes esferas sociais — públicas e privadas","source_page":33}]},{"title":"Estudo das práticas corporais: a linguagem corporal como integradora social e formadora de identidade","subject_code":"languages_codes","source_page":33,"items":[{"text":"Performance corporal e identidades juvenis","source_page":33},{"text":"Possibilidades de vivência crítica e emancipada do lazer","source_page":33},{"text":"Mitos e verdades sobre os corpos masculino e feminino na sociedade atual","source_page":33},{"text":"Exercício físico e saúde","source_page":33},{"text":"Corpo e expressão artística e cultural","source_page":33},{"text":"O corpo no mundo dos símbolos e como produção da cultura","source_page":33},{"text":"Práticas corporais e autonomia","source_page":33},{"text":"Condicionamentos e esforços físicos","source_page":33},{"text":"O esporte","source_page":34},{"text":"A dança","source_page":34},{"text":"As lutas","source_page":34},{"text":"Os jogos","source_page":34},{"text":"As brincadeiras","source_page":34}]},{"title":"Produção e recepção de textos artísticos: interpretação e representação do mundo para o fortalecimento dos processos de identidade e cidadania","subject_code":"languages_codes","source_page":34,"items":[{"text":"Artes Visuais: estrutura morfológica, sintática, o contexto da obra artística, o contexto da comunidade","source_page":34},{"text":"Teatro: estrutura morfológica, sintática, o contexto da obra artística, o contexto da comunidade, as fontes de criação","source_page":34},{"text":"Música: estrutura morfológica, sintática, o contexto da obra artística, o contexto da comunidade, as fontes de criação","source_page":34},{"text":"Dança: estrutura morfológica, sintática, o contexto da obra artística, o contexto da comunidade, as fontes de criação","source_page":34},{"text":"Conteúdos estruturantes das linguagens artísticas (Artes Visuais, Dança, Música, Teatro), elaborados a partir de suas estruturas morfológicas e sintáticas","source_page":34},{"text":"Inclusão, diversidade e multiculturalidade: a valorização da pluralidade expressada nas produções estéticas e artísticas das minorias sociais e das pessoas com deficiência","source_page":34}]},{"title":"Estudo do texto literário: relações entre produção literária e processo social, concepções artísticas, procedimentos de construção e recepção de textos","subject_code":"languages_codes","source_page":34,"items":[{"text":"Produção literária e processo social","source_page":34},{"text":"Processos de formação literária e de formação nacional","source_page":34},{"text":"Produção de textos literários, sua recepção e a constituição do patrimônio literário nacional","source_page":35},{"text":"Relações entre a dialética cosmopolitismo/localismo e a produção literária nacional","source_page":35},{"text":"Elementos de continuidade e ruptura entre os diversos momentos da literatura brasileira","source_page":35},{"text":"Associações entre concepções artísticas e procedimentos de construção do texto literário em seus gêneros (épico/narrativo, lírico e dramático) e formas diversas","source_page":35},{"text":"Articulações entre os recursos expressivos e estruturais do texto literário e o processo social relacionado ao momento de sua produção","source_page":35},{"text":"Representação literária: natureza, função, organização e estrutura do texto literário","source_page":35},{"text":"Relações entre literatura, outras artes e outros saberes","source_page":35}]},{"title":"Estudo dos aspectos linguísticos em diferentes textos: recursos expressivos da língua, procedimentos de construção e recepção de textos","subject_code":"languages_codes","source_page":35,"items":[{"text":"Organização da macroestrutura semântica e a articulação entre ideias e proposições (relações lógico-semânticas)","source_page":35}]},{"title":"Estudo do texto argumentativo, seus gêneros e recursos linguísticos: argumentação — tipo, gêneros e usos em Língua Portuguesa","subject_code":"languages_codes","source_page":35,"items":[{"text":"Formas de apresentação de diferentes pontos de vista","source_page":35},{"text":"Organização e progressão textual","source_page":35},{"text":"Papéis sociais e comunicativos dos interlocutores, relação entre usos e propósitos comunicativos, função sociocomunicativa do gênero, aspectos da dimensão espaçotemporal em que se produz o texto","source_page":35}]},{"title":"Estudo dos aspectos linguísticos da Língua Portuguesa: usos da língua — norma culta e variação linguística","subject_code":"languages_codes","source_page":36,"items":[{"text":"Uso dos recursos linguísticos em relação ao contexto em que o texto é constituíd