rce_page":16,"abilities":[{"code":"mathematics.H6","number":6,"text":"Interpretar a localização e a movimentação de pessoas/objetos no espaço tridimensional e sua representação no espaço bidimensional.","source_page":16},{"code":"mathematics.H7","number":7,"text":"Identificar características de figuras planas ou espaciais.","source_page":16},{"code":"mathematics.H8","number":8,"text":"Resolver situação-problema que envolva conhecimentos geométricos de espaço e forma.","source_page":16},{"code":"mathematics.H9","number":9,"text":"Utilizar conhecimentos geométricos de espaço e forma na seleção de argumentos propostos como solução de problemas do cotidiano.","source_page":16}]},{"code":"mathematics.C3","number":3,"text":"Construir noções de grandezas e medidas para a compreensão da realidade e a solução de problemas do cotidiano.","source_page":16,"abilities":[{"code":"mathematics.H10","number":10,"text":"Identificar relações entre grandezas e unidades de medida.","source_page":16},{"code":"mathematics.H11","number":11,"text":"Utilizar a noção de escalas na leitura de representação de situação do cotidiano.","source_page":16},{"code":"mathematics.H12","number":12,"text":"Resolver situação-problema que envolva medidas de grandezas.","source_page":16},{"code":"mathematics.H13","number":13,"text":"Avaliar o resultado de uma medição na construção de um argumento consistente.","source_page":16},{"code":"mathematics.H14","number":14,"text":"Avaliar proposta de intervenção na realidade utilizando conhecimentos geométricos relacionados a grandezas e medidas.","source_page":16}]},{"code":"mathematics.C4","number":4,"text":"Construir noções de variação de grandezas para a compreensão da realidade e a solução de problemas do cotidiano.","source_page":17,"abilities":[{"code":"mathematics.H15","number":15,"text":"Identificar a relação de dependência entre grandezas.","source_page":17},{"code":"mathematics.H16","number":16,"text":"Resolver situação-problema envolvendo a variação de 