:18}]},{"code":"mathematics.C7","number":7,"text":"Compreender o caráter aleatório e não determinístico dos fenômenos naturais e sociais, e utilizar instrumentos adequados para medidas, determinação de amostras e cálculos de probabilidade para interpretar informações de variáveis apresentadas em uma distribuição estatística.","source_page":18,"abilities":[{"code":"mathematics.H27","number":27,"text":"Calcular medidas de tendência central ou de dispersão de um conjunto de dados expressos em uma tabela de frequências de dados agrupados (não em classes) ou em gráficos.","source_page":18},{"code":"mathematics.H28","number":28,"text":"Resolver situação-problema que envolva conhecimentos de estatística e probabilidade.","source_page":18},{"code":"mathematics.H29","number":29,"text":"Utilizar conhecimentos de estatística e probabilidade como recurso para a construção de argumentação.","source_page":18},{"code":"mathematics.H30","number":30,"text":"Avaliar propostas de intervenção na realidade utilizando conhecimentos de estatística e probabilidade.","source_page":18}]}],"object_groups":[{"title":"Conhecimentos numéricos","subject_code":"mathematics","source_page":37,"items":[{"text":"Operações em conjuntos numéricos (naturais, inteiros, racionais e reais)","source_page":37},{"text":"Desigualdades, divisibilidade, fatoração, razões e proporções, porcentagem e juros","source_page":37},{"text":"Relações de dependência entre grandezas, sequências e progressões, princípios de contagem","source_page":37}]},{"title":"Conhecimentos geométricos","subject_code":"mathematics","source_page":37,"items":[{"text":"Características das figuras geométricas planas e espaciais","source_page":37},{"text":"Grandezas, unidades de medida e escalas","source_page":37},{"text":"Comprimentos, áreas e volumes","source_page":37},{"text":"Ângulos","source_page":37},{"text":"Posições de retas","source_page":37},{"text":"Simetrias de figuras planas ou espaciais","source_page":37},{"text":"Congruência e semelhança de triângulos","source_page":37},{"text":"Teorema de Tales","source_page":37},{"text":"Relações métricas nos triângulos","source_page":38},{"text":"Circunferências","source_page":38},{"text":"Trigonometria do ângulo agudo","source_page":38}]},{"title":"Conhecimentos de estatística e probabilidade","subject_code":"mathematics","source_page":38,"items":[{"text":"Representação e análise de dados","source_page":38},{"text":"Medidas de tendência central (médias, moda e mediana)","source_page":38},{"text":"Desvios e variância","source_page":38},{"text":"Noções de probabilidade","source_page":38}]},{"title":"Conhecimentos algébricos","subject_code":"mathematics","source_page":38,"items":[{"text":"Gráficos e funções","source_page":38},{"text":"Funções algébricas do 1º e do 2º graus, polinomiais, racionais, exponenciais e logarítmicas","source_page":38},{"text":"Equações e inequações","source_page":38},{"text":"Relações no ciclo trigonométrico e funções trigonométricas","source_page":38}]},{"title":"Conhecimentos algébricos/geométricos","subject_code":"mathematics","source_page":38,"items":[{"text":"Plano cartesiano","source_page":38},{"text":"Retas","source_page":38},{"text":"Circunferências","source_page":38},{"text":"Paralelismo e perpendicularidade, sistemas de equações","source_page":38}]}]},{"code":"natural_sciences","name":"Ciências da Natureza e suas Tecnologias","competencies":[{"code":"natural_sciences.C1","number":1,"text":"Compreender as ciências naturais e as tecnologias a elas associadas como construções humanas, percebendo seus papéis nos processos de produção e no desenvolvimento econômico e social da humanidade.","source_page":19,"abilities":[{"code":"natural_sciences.H1","number":1,"text":"Reconhecer características ou propriedades de fenômenos ondulatórios ou oscilatórios, relacionando-os a seus usos em diferentes contextos.","source_page":19},{"code":"natural_sciences.H2","number":2,"text":"Associar a solução de problemas de comunicação, transporte, saúde ou outro, com o correspondente desenvolvimento científico e tecnológico.","source_page":19},{"code":"natural_sciences.H3","number":3,"text":"Confrontar interpretações científicas com interpretações baseadas no senso comum, ao longo do tempo ou em diferentes culturas.","source_page":19},{"code":"natural_sciences.H4","number":4,"text":"Avaliar propostas de intervenção no ambiente, considerando a qualidade da vida humana ou as medidas de conservação, recuperação ou utilização sustentável da biodiversidade.","source_page":19}]},{"code":"natural_sciences.C2","number":2,"text":"Identificar a presença e aplicar as tecnologias associadas às ciências naturais em diferentes contextos.","source_page":20,"abilities":[{"code":"natural_sciences.H5","number":5,"text":"Dimensionar circuitos ou dispositivos elétricos de uso cotidiano.","source_page":20},{"code":"natural_sciences.H6","number":6,"text":"Relacionar informações para compreender manuais de instalação ou utilização de aparelhos ou sistemas tecnológicos de uso comum.","source_page":20},{"code":"natural_sciences.H7","number":7,"text":"Selecionar testes de controle, parâmetros ou critérios para a comparação de materiais e produtos, tendo em vista a defesa do consumidor, a saúde do trabalhador ou a qualidade de vida.","source_page":20}]},{"code":"natural_sciences.C3","number":3,"text":"Associar intervenções que resultam em degradação ou conservação ambiental a processos produtivos e sociais e a instrumentos ou ações científico-tecnológicos.","source_page":20,"abilities":[{"code":"natural_sciences.H8","number":8,"text":"Identificar etapas em processos de obtenção, transformação, utilização ou reciclagem de recursos naturais, energéticos ou matérias-primas, considerando processos biológicos, químicos ou físicos neles envolvidos.","source_page":20},{"code":"natural_sciences.H9","number":9,"text":"Compreender a importância dos ciclos biogeoquímicos ou do fluxo de energia para a vida ou da ação de agentes ou fenômenos que possam causar alterações nesses processos.","source_page":20},{"code":"natural_sciences.H10","number":10,"text":"Analisar perturbações ambientais, identificando fontes, transporte e(ou) destino dos poluentes ou prevendo efeitos em sistemas naturais, produtivos ou sociais.","source_page":20},{"code":"natural_sciences.H11","number":11,"text":"Reconhecer benefícios, limitações e aspectos éticos da biotecnologia, considerando estruturas e processos biológicos envolvidos em produtos biotecnológicos.","source_page":20},{"code":"natural_sciences.H12","number":12,"text":"Avaliar impactos em ambientes naturais decorrentes de atividades sociais ou econômicas, considerando interesses contraditórios.","source_page":20}]},{"code":"natural_sciences.C4","number":4,"text":"Compreender interações entre organismos e ambiente, em particular aquelas relacionadas à saúde humana, relacionando conhecimentos científicos, aspectos culturais e características individuais.","source_page":21,"abilities":[{"code":"natural_sciences.H13","number":13,"text":"Reconhecer mecanismos de transmissão da vida, prevendo ou explicando a manifestação de características dos seres vivos.","source_page":21},{"code":"natural_sciences.H14","number":14,"text":"Identificar padrões em fenômenos e processos vitais dos organismos, como manutenção do equilíbrio interno, defesa, relações com o ambiente, sexualidade, entre outros.","source_page":21},{"code":"natural_sciences.H15","number":15,"text":"Interpretar modelos e experimentos para explicar fenômenos ou processos biológicos em qualquer nível de organização dos sistemas biológicos.","source_page":21},{"code":"natural_sciences.H16","number":16,"text":"Compreender o papel da evolução na produção de padrões, processos biológicos ou na organização taxonômica dos seres vivos.","source_page":21}]},{"code":"natural_sciences.C5","number":5,"text":"Entender métodos e procedimentos próprios das ciências naturais e aplicá-los em diferentes contextos.","source_page":21,"abilities":[{"code":"natural_sciences.H17","number":17,"text":"Relacionar informações apresentadas em diferentes formas de linguagem e representação usadas nas ciências físicas, químicas ou biológicas, como texto discursivo, gráficos, tabelas, relações matemáticas ou linguagem simbólica.","source_page":21},{"code":"natural_sciences.H18","number":18,"text":"Relacionar propriedades físicas, químicas ou biológicas de produtos, sistemas ou procedimentos tecnológicos às finalidades a que se destinam.","source_page":21},{"code":"natural_sciences.H19","number":19,"text":"Avaliar métodos, processos ou procedimentos das ciências naturais que contribuam para diagnosticar ou solucionar problemas de ordem social, econômica ou ambiental.","source_page":21}]},{"code":"natural_sciences.C6","number":6,"text":"Apropriar-se de conhecimentos da física para, em situações-problema, interpretar, avaliar ou planejar intervenções científico-tecnológicas.","source_page":22,"abilities":[{"code":"natural_sciences.H20","number":20,"text":"Caracterizar causas ou efeitos dos movimentos de partículas, substâncias, objetos ou corpos celestes.","source_page":22},{"code":"natural_sciences.H21","number":21,"text":"Utilizar leis físicas e(ou) químicas para interpretar processos naturais ou tecno-lógicos inseridos no contexto da termodinâmica e(ou) do eletromagnetismo.","source_page":22},{"code":"natural_sciences.H22","number":22,"text":"Compreender fenômenos decorrentes da interação entre a radiação e a matéria em suas manifestações em processos naturais ou tecnológicos, ou em suas implicações biológicas, sociais, econômicas ou ambientais.","source_page":22},{"code":"natural_sciences.H23","number":23,"text":"Avaliar possibilidades de geração, uso ou transformação de energia em ambientes específicos, considerando implicações éticas, ambientais, sociais e(ou) econômicas.","source_page":22}]},{"code":"natural_sciences.C7","number":7,"text":"Apropriar-se de conhecimentos da química para, em situações-problema, interpretar, avaliar ou planejar intervenções científico-tecnológicas.","source_page":22,"abilities":[{"code":"natural_sciences.H24","number":24,"text":"Utilizar códigos e nomenclatura da química para caracterizar materiais, substâncias ou transformações químicas.","source_page":22},{"code":"natural_sciences.H25","number":25,"text":"Caracterizar materiais ou substâncias, identificando etapas, rendimentos ou implicações biológicas, sociais, econômicas ou ambientais de sua obtenção ou produção.","source_page":22},{"code":"natural_sciences.H26","number":26,"text":"Avaliar implicações sociais, ambientais e(ou) econômicas na produção ou no consumo de recursos energéticos ou minerais, identificando transformações químicas ou de energia envolvidas nesses processos.","source_page":22},{"code":"natural_sciences.H27","number":27,"text":"Avaliar propostas de intervenção no meio ambiente aplicando conhecimentos químicos, observando riscos ou benefícios.","source_page":22}]},{"code":"natural_sciences.C8","number":8,"text":"Apropriar-se de conhecimentos da biologia para, em situações-problema, interpretar, avaliar ou planejar intervenções científico-tecnológicas.","source_page":23,"abilities":[{"code":"natural_sciences.H28","number":28,"text":"Associar características adaptativas dos organismos com seu modo de vida ou com seus limites de distribuição em diferentes ambientes, em especial em ambientes brasileiros.","source_page":23},{"code":"natural_sciences.H29","number":29,"text":"Interpretar experimentos ou técnicas que utilizam seres vivos, analisando implicações para o ambiente, a saúde, a produção de alimentos, as matérias-primas ou os produtos industriais.","source_page":23},{"code":"natural_sciences.H30","number":30,"text":"Avaliar propostas de alcance individual ou coletivo, identificando aquelas que visam à preservação e à implementação da saúde individual, coletiva ou do ambiente.","source_page":23}]}],"object_groups":[{"title":"Conhecimentos básicos e fundamentais","