);

on conflict (code) do nothing;

on conflict (catalog_version_id,skill_code) do nothing;

do $validation$
begin
  if (select status from public.exam_catalog_versions where id='27000000-0000-4000-8000-000000000100'::uuid) <> 'draft' then
    raise exception 'Catalog must remain draft';
  end if;
  if (select published_at from public.exam_catalog_versions where id='27000000-0000-4000-8000-000000000100'::uuid) is not null then
    raise exception 'Draft catalog cannot have published_at';
  end if;
  if (select count(*) from public.exam_catalog_skills where catalog_version_id='27000000-0000-4000-8000-000000000100'::uuid) <> 378 then
    raise exception 'Unexpected catalog skill count';
  end if;
end
$validation$;
